import {readSkin,EXAMPLE_SKIN,MAX_SKIN_BYTES} from './skin-format.js';
import {PRELAUNCH,RELEASE_LINKS} from './branding.js';
let selected=null,ticket=0;const status=document.getElementById('status'),apply=document.getElementById('apply');
document.getElementById('example').onclick=()=>{const url=URL.createObjectURL(new Blob([JSON.stringify(EXAMPLE_SKIN,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='reckoner-skin-example.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
document.getElementById('file').onchange=async event=>{const version=++ticket,file=event.target.files[0];event.target.value='';selected=null;apply.disabled=true;document.getElementById('preview').textContent='No skin selected.';if(!file)return;try{if(file.size>MAX_SKIN_BYTES)throw Error('Choose a skin under 16 KB.');const next=readSkin(await file.text());if(version!==ticket)return;selected=next;document.getElementById('preview').textContent=JSON.stringify(next,null,2);apply.disabled=false;status.textContent='Appearance validated. Creator identity and license statements are self-declared.';}catch(error){if(version===ticket)status.textContent=error.message;}};
apply.onclick=()=>{try{if(!selected)return;localStorage.setItem('reckoner-community-skin-v1',JSON.stringify(selected));localStorage.setItem('reckoner-appearance-v1','community');status.textContent='Skin saved for this device. Open Reckoner Settings and choose My community skin if it is not already applied. Review records are unchanged.';}catch{status.textContent='Device storage unavailable. Keep the skin file and try again later.';}};
if(!PRELAUNCH){document.getElementById('contribute').hidden=false;document.getElementById('contribute').href=RELEASE_LINKS.repository+'/issues/new/choose';document.getElementById('held').hidden=true;}
